// These views use only backend-authorized data. Permissions are enforced again by the API.
export function teacherShiftPanel({role,day,today,events,id,e}) {
  if(role!=='teacher')return '';
  const latest=events.find(event=>event.teacher===id),onShift=Boolean(latest?.signed_in),current=day===today;
  const status=onShift?'On shift':'Off shift';
  return `<section class="teacher-shift-bar" aria-label="My shift"><div class="teacher-shift-copy"><span class="teacher-shift-icon" aria-hidden="true">${uiIcon('staff')}</span><div><strong>My shift <span class="status-pill ${onShift?'status-active':'status-neutral'}">${status}</span></strong><p>${current?'Use the button to record your shift. Logging out of the app does not end your shift.':`Viewing ${e(day)}. Switch to today to record your shift.`}</p>${latest?`<small>Last ${latest.signed_in?'sign-in':'sign-out'}: <time datetime="${e(latest.at)}">${e(new Date(latest.at).toLocaleTimeString([], {hour:'numeric',minute:'2-digit',timeZone:'America/New_York'}))} ET</time></small>`:''}</div></div><div class="teacher-shift-actions">${current?'':`<button type="button" data-shift-today>Go to today</button>`}<button type="button" class="primary" data-action="shift" data-in="${onShift?'0':'1'}" ${current?'':'disabled'}>${onShift?'Sign Out of Shift':'Sign In to Shift'}</button></div></section>`;
}
export function programPanel(tab,{data,admin,day,escapeHTML:e,heading,renderGroups,query='',schedule,schedulePanel,today}) {
  query=query.trim().toLowerCase();
  if(tab==='schedule')return schedulePanel({schedule,admin,today,e,heading});
  const students=data.students.filter(s=>s.active && (s.name+' '+s.grade+' '+(s.group_name??'')).toLowerCase().includes(query));
  function eventGroups(events, key, renderEvent) {
    if (!events.length) return '';
    const members=[...new Map(events.map(event=>{
      const student=data.students.find(s=>s.id===event.student);
      return [event.student,{...student,id:event.student,name:event.student_name??student?.name??('Student '+event.student)}];
    })).values()].filter(s=>!query||(s.name+' '+(s.group_name??'')).toLowerCase().includes(query));
    if(!members.length)return '<p class="empty">No records match this search.</p>';
    return renderGroups(members,key,students=>students.map(s=>`<details class="student-editor" data-manage-key="${key}-student-${s.id}"><summary class="student-summary">${e(s.name)}</summary>${events.filter(event=>event.student===s.id).map(renderEvent).join('')}</details>`).join(''));
  }
  const chooseStudent=`<label>Student<select name="student" required><option value="">Choose a student</option>${[...new Map(students.map(s=>[s.group_id??'unassigned',s.group_name??'Unassigned students']))].map(([id,name])=>`<optgroup label="${e(name)}">${students.filter(s=>(s.group_id??'unassigned')===id).map(s=>`<option value="${s.id}">${e(s.name)}</option>`).join('')}</optgroup>`).join('')}</select></label>`;
  if(tab==='incidents')return heading('Incidents','Teachers see their own reports; administrators review all reports.')+
    `<details class="entry module-drawer incident-drawer" data-manage-key="record-incident"><summary>+ Report Incident</summary><form data-form="incident">${chooseStudent}<label>Category<select name="category"><option>Injury</option><option>Behavior</option><option>Safety</option><option>Other</option></select></label><label>What happened<textarea name="detail" maxlength="2000" required></textarea></label><label>Action taken<textarea name="actionTaken" maxlength="2000" required></textarea></label><button class="primary">Record incident</button></form></details>`+
    (data.incidents.length?eventGroups(data.incidents,'incidents',i=>`<article class="entry"><h3>${e(i.student_name)} <span class="category-pill category-${['Injury','Behavior','Safety'].includes(i.category)?i.category.toLowerCase():'other'}">${e(i.category)}</span></h3><p>${e(i.detail)}</p><p>Action: ${e(i.action_taken)}</p><p class="muted">${e(i.recorded_by)} · ${e(new Date(i.at).toLocaleString())}</p>${i.resolved_at?`<p>Resolution: ${e(i.resolution)} (${e(i.resolved_by)})</p>`:admin?`<form data-form="resolve-incident"><input name="id" type="hidden" value="${e(i.id)}"><label>Resolution<textarea name="resolution" maxlength="2000" required></textarea></label><button>Resolve incident</button></form>`:'<span class="badge">Open</span>'}</article>`):richEmpty('No incident reports for this date.','A calm day starts with clear records. Use Report Incident whenever a report is needed.','shield'));
  if(tab==='pickup')return heading('Student pickup','Verify identity against the authorized contact before releasing a student.')+
    renderGroups(students,'pickup',members=>members.map(s=>{
      const contacts=data.pickupContacts.filter(c=>c.student===s.id),collected=data.pickups.find(p=>p.student===s.id&&!p.voided_at);
      return `<details class="student-editor" data-manage-key="pickup-student-${s.id}"><summary class="student-summary"><strong>${e(s.name)}</strong><span>Grade ${e(s.grade)}</span><span class="badge pickup-status ${collected?'pickup-collected':'pickup-pending'}">${collected?'Pickup recorded':'No pickup recorded'}</span></summary><div class="student-controls"><span class="verification-badge ${contacts.length?'contacts-available':'contacts-needed'}">${uiIcon('shield')}${contacts.length?'Authorized contacts on file':'Authorization needed'}</span>${admin?`<details><summary>Authorize pickup contact</summary><form data-form="pickup-contact"><input name="student" type="hidden" value="${s.id}"><label>Full name<input name="name" maxlength="120" required></label><label>Relationship<input name="relationship" maxlength="80" required></label><button>Add authorized contact</button></form></details>`:''}${contacts.map(c=>`<p>${e(c.name)} (${e(c.relationship)}) ${admin?`<button data-action="contact-disable" data-id="${e(c.id)}">Revoke authorization</button>`:''}</p>`).join('')||'<p>No authorized pickup contacts.</p>'}${collected?`<p class="badge">Picked up by ${e(collected.contact_name)} at ${e(new Date(collected.at).toLocaleTimeString())}</p>${admin?`<form data-form="void-pickup"><input name="id" type="hidden" value="${e(collected.id)}"><label>Correction reason<input name="reason" maxlength="500" required></label><button>Void mistaken pickup</button></form>`:''}`:contacts.length?`<form data-form="pickup"><input name="student" type="hidden" value="${s.id}"><label>Authorized adult<select name="contact" required><option value="">Choose contact</option>${contacts.map(c=>`<option value="${e(c.id)}">${e(c.name)}</option>`).join('')}</select></label><label>Note<input name="note" maxlength="500"></label><label><input type="checkbox" name="identityChecked" required>Identity checked against authorization</label><button class="primary" ${day===data.today?'':'disabled'}>Record pickup</button></form>`:''}</div></details>`;
    }).join(''))+`<details class="entry pickup-audit-timeline" data-manage-key="pickup-audit"><summary>Pickup audit (${data.pickups.length} events)</summary><p>Corrections preserve the original event.</p>`+(eventGroups(data.pickups,'pickup-audit',p=>`<div class="entry"><strong>${e(p.student_name)}</strong> · ${e(p.contact_name)}<p>${e(p.recorded_by)} · ${e(new Date(p.at).toLocaleString())}</p><p>${e(p.note)}</p>${p.voided_at?`<p>Voided: ${e(p.void_reason)} (${e(p.voided_by)})</p>`:''}</div>`)||'<p class="empty">No pickups for this date.</p>')+'</details>';
  if(tab==='reports'&&admin)return heading('Report exports','Exports include archived records. Keep downloaded files private.')+`<div class="entry report-studio"><form data-form="export"><div class="report-type-grid" aria-label="Select report type">${[['attendance','Attendance'],['homework','Homework'],['staff','Staff Log'],['activities','Activities'],['incidents','Incidents'],['pickup','Pickup']].map(([value,label])=>`<button type="button" class="report-type-card" data-report-choice="${value}" aria-pressed="${value==='attendance'}">${uiIcon(value==='pickup'?'shield':value==='incidents'?'incident':value==='staff'?'staff':value==='activities'?'activity':value==='homework'?'homework':'attendance')}<strong>${label}</strong><span><i>CSV</i><i>PDF</i></span></button>`).join('')}</div><label>Report<select name="type">${['attendance','homework','staff','activities','incidents','pickup'].map(t=>`<option>${t}</option>`).join('')}</select></label><label>From<input name="from" type="date" value="${e(day)}" required></label><label>Through<input name="to" type="date" value="${e(day)}" required></label><button class="primary" type="submit" name="format" value="csv">Download CSV</button><button type="submit" name="format" value="pdf">Download PDF</button></form></div>`;
  return null;
}

// Dashboard calculations use the same authorized desk responses as the operational views.
export function summarizeDesk(data) {
  const students=data.students.filter(s=>s.active),total=students.length;
  const present=students.filter(s=>s.attendance==='Present').length,tardy=students.filter(s=>s.attendance==='Tardy').length,absent=students.filter(s=>s.attendance==='Absent').length;
  const complete=students.filter(s=>s.homework==='Complete').length;
  const latest=new Map();for(const event of data.staff)if(!latest.has(event.teacher))latest.set(event.teacher,event);
  const collected=new Set(data.pickups.filter(p=>!p.voided_at).map(p=>p.student));
  return {total,present,tardy,absent,complete,attendanceRate:total?present/total*100:null,homeworkRate:total?complete/total*100:null,hasAttendance:present+tardy+absent>0,hasHomework:students.some(s=>['Complete','Needs Help','No Homework'].includes(s.homework)),onShift:[...latest.values()].filter(e=>e.signed_in).length,completedShifts:[...latest.values()].filter(e=>!e.signed_in).length,pending:students.filter(s=>['Present','Tardy'].includes(s.attendance)&&!collected.has(s.id)).length,openIncidents:data.incidents.filter(i=>!i.resolved_at).length};
}
export function weekDays(day) {
  return Array.from({length:7},(_,index)=>{const date=new Date(day+'T12:00:00Z');date.setUTCDate(date.getUTCDate()-6+index);return date.toISOString().slice(0,10);});
}
export const uiIcon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">${{
 dashboard:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="11" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="18" width="7" height="3" rx="1"/>',
 attendance:'<path d="M8 3v4m8-4v4M4 10h16"/><rect x="4" y="5" width="16" height="16" rx="3"/><path d="m8 15 3 3 5-6"/>',
 homework:'<path d="M5 3h14v18H5zM8 8h8m-8 4h5m-5 4h3"/>',
 staff:'<circle cx="9" cy="7" r="3"/><path d="M3 20v-3a6 6 0 0 1 10-4"/><circle cx="17" cy="17" r="4"/><path d="M17 15v2l1 1"/>',
 shield:'<path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6z"/><path d="m8 12 3 3 5-6"/>',
 incident:'<path d="m12 3 10 18H2zM12 9v5m0 3v.1"/>',
 activity:'<path d="m13 2-9 12h7l-1 8 10-12h-7z"/>',
 arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',
 trend:'<path d="m3 17 6-6 4 4 8-10M15 5h6v6"/>',
 schedule:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 report:'<path d="M5 3h10l4 4v14H5zM14 3v5h5M8 17v-3m4 3v-6m4 6v-4"/>'
}[name]??'<circle cx="12" cy="12" r="8"/>'}</svg>`;
export function richEmpty(title,detail,icon='dashboard') {
  return `<div class="empty rich-empty"><span class="empty-symbol">${uiIcon(icon)}</span><strong>${title}</strong><p>${detail}</p></div>`;
}
const dashboardDate=day=>new Date(day+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'});
function changeIndicator(current,previous,key,observed) {
  if(!previous||!current[observed]||!previous[observed]||current[key]===null||previous[key]===null)return '<span class="kpi-context">No prior-day comparison</span>';
  const difference=current[key]-previous[key],tone=difference>0?'up':difference<0?'down':'flat';
  return `<span class="kpi-change ${tone}">${difference>0?'↑ ':difference<0?'↓ ':'↔ '}${Math.abs(difference).toFixed(1)} pp</span><span class="kpi-context">vs previous day</span>`;
}
function countChange(current,previous,key,noun,inverse=false) {
  if(!previous)return '<span class="kpi-context">No prior-day comparison</span>';
  const difference=current[key]-previous[key],tone=difference===0?'flat':(difference>0)!==inverse?'up':'down';
  return `<span class="kpi-change ${tone}">${difference>0?'↑ ':difference<0?'↓ ':'↔ '}${Math.abs(difference)} ${noun}</span><span class="kpi-context">vs previous day</span>`;
}
export function dashboardPanel({data,day,history=[],historyStatus='idle',schedule,scheduleUnavailable=false,updatedAt,e,heading}) {
  const stats=summarizeDesk(data),previous=history.find(point=>point.day===weekDays(day)[5])?.stats;
  const percent=value=>value===null?'—':Math.round(value)+'%';
  const kpi=(label,value,detail,icon,footer)=>`<article class="card executive-kpi"><div class="kpi-label">${e(label)}<span class="kpi-icon">${uiIcon(icon)}</span></div><strong>${e(value)}</strong><p>${e(detail)}</p><div class="kpi-footer">${footer}</div></article>`;
  const groups=[...data.groups.map(g=>({...g,students:data.students.filter(s=>s.active&&s.group_id===g.id)}))];
  const unassigned=data.students.filter(s=>s.active&&s.group_id==null);if(unassigned.length)groups.push({id:'none',name:'Unassigned',students:unassigned});
  const chartWidth=Math.max(580,groups.length*130),chartHeight=266,plotTop=26,baseline=204,plotHeight=178,max=Math.max(1,...groups.map(g=>g.students.length));
  const colors=['#1684a0','#e7ac47','#d47c8b','#8a83c2'];
  const groupChart=groups.length?`<div class="chart-scroll"><svg class="group-breakdown" style="min-width:${Math.max(530,groups.length*115)}px" viewBox="0 0 ${chartWidth} ${chartHeight}" role="img" aria-label="Student counts by group: present, tardy, absent and homework complete">
    <title>Attendance and homework by group for ${e(day)}</title>${[0,.5,1].map(n=>`<g><line x1="38" y1="${baseline-n*plotHeight}" x2="${chartWidth-16}" y2="${baseline-n*plotHeight}" class="chart-grid"/><text x="27" y="${baseline-n*plotHeight+4}" text-anchor="end" class="chart-axis">${Math.round(max*n)}</text></g>`).join('')}
    ${groups.map((group,index)=>{const span=(chartWidth-60)/groups.length,center=44+span*(index+.5),values=['Present','Tardy','Absent'].map(status=>group.students.filter(s=>s.attendance===status).length);values.push(group.students.filter(s=>s.homework==='Complete').length);return `<g class="chart-group" tabindex="0" role="img" aria-label="${e(group.name)}: ${values[0]} present, ${values[1]} tardy, ${values[2]} absent, ${values[3]} homework complete; ${group.students.length} enrolled"><title>${e(group.name)} · Present ${values[0]}, Tardy ${values[1]}, Absent ${values[2]}, Homework complete ${values[3]} / ${group.students.length}</title>${values.map((value,i)=>{const height=value/max*plotHeight;return `<rect x="${center-39+i*20}" y="${baseline-height}" width="14" height="${Math.max(height,1)}" rx="3" fill="${colors[i]}" opacity="${value?1:.22}"/>`;}).join('')}<text x="${center}" y="229" text-anchor="middle" class="chart-group-label">${e(group.name.replace(/\s*\([^)]*\)/,''))}</text><text x="${center}" y="247" text-anchor="middle" class="chart-axis">${group.students.length} students</text></g>`;}).join('')}</svg></div>`:richEmpty('Your groups will appear here','Create groups and enroll students in Manage Program.','attendance');
  const trendPoints=weekDays(day).map(date=>({day:date,stats:history.find(p=>p.day===date)?.stats??(date===day?stats:null)}));
  const hasTrend=trendPoints.some(p=>p.stats?.hasAttendance||p.stats?.hasHomework);
  function trendSeries(key,flag,color){
    const segments=[];let segment=[];trendPoints.forEach((p,i)=>{if(p.stats?.[flag]&&p.stats[key]!==null)segment.push([54+i*79,190-p.stats[key]*1.5,p]);else if(segment.length){segments.push(segment);segment=[];}});if(segment.length)segments.push(segment);
    return segments.map(points=>`<path d="M${points.map(p=>p[0]+','+p[1]).join(' L')} L${points.at(-1)[0]},190 L${points[0][0]},190 Z" fill="${color}" opacity=".06"/><path d="M${points.map(p=>p[0]+','+p[1]).join(' L')}" fill="none" stroke="${color}" stroke-width="2.5" stroke-linejoin="round"/>${points.map(([x,y,p])=>`<circle tabindex="0" role="img" aria-label="${e(dashboardDate(p.day))} ${key==='attendanceRate'?'attendance':'homework'} ${Math.round(p.stats[key])}%" cx="${x}" cy="${y}" r="4" fill="white" stroke="${color}" stroke-width="2"><title>${e(dashboardDate(p.day))}: ${Math.round(p.stats[key])}% (${key==='attendanceRate'?p.stats.present:p.stats.complete} / ${p.stats.total})</title></circle>`).join('')}`).join('');
  }
  const trend=historyStatus==='loading'?`<div class="chart-skeleton" role="status" aria-label="Loading seven-day history"><span></span><span></span><span></span><span></span><span></span><span></span><span></span></div><p class="chart-note">Loading recorded results for the last seven days…</p>`:hasTrend?`<svg class="weekly-trend" viewBox="0 0 580 246" role="img" aria-label="Seven-day attendance and homework completion rates"><title>Recorded results only; gaps indicate unmarked or unavailable days.</title>${[0,50,100].map(value=>`<line x1="42" y1="${190-value*1.5}" x2="548" y2="${190-value*1.5}" class="chart-grid"/><text x="33" y="${194-value*1.5}" text-anchor="end" class="chart-axis">${value}%</text>`).join('')}${trendSeries('attendanceRate','hasAttendance','#1684a0')}${trendSeries('homeworkRate','hasHomework','#8a83c2')}${trendPoints.map((p,i)=>`<text x="${54+i*79}" y="221" text-anchor="middle" class="chart-axis">${e(dashboardDate(p.day))}</text>${p.stats?.hasAttendance||p.stats?.hasHomework?'':`<text x="${54+i*79}" y="182" text-anchor="middle" class="chart-axis"><title>${p.stats?'No attendance or homework marked':'History unavailable'}</title>—</text>`}`).join('')}</svg>`:richEmpty('A little history goes a long way','Attendance and homework trends appear as your team records results.','trend');
  const staffLatest=new Map();for(const event of data.staff)if(!staffLatest.has(event.teacher))staffLatest.set(event.teacher,event);
  const onShift=[...staffLatest.values()].filter(event=>event.signed_in);
  let currentBlocks=[];
  if(schedule?.day===day){const timeParts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date()).map(p=>[p.type,p.value]));const now=timeParts.hour+':'+timeParts.minute;
    currentBlocks=schedule.groups.filter(g=>g.published).flatMap(g=>g.slots.filter(slot=>day===data.today?slot.start<=now&&now<slot.end:true).map(slot=>({group:g.name,...slot})));}
  return `<div class="executive-dashboard">${heading('Dashboard','A clear view of your program, one day at a time.',`<button type="button" class="dashboard-refresh" data-dashboard-refresh>${uiIcon('trend')}Refresh summary</button>`)}
    <div class="dashboard-dateline"><span class="soft-pill">${e(dashboardDate(day))}${day===data.today?' · Today':''}</span><span>Updated ${updatedAt?e(updatedAt.toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit',timeZone:'America/New_York'}))+' ET':'on refresh'}</span></div>
    <div class="executive-kpis">${kpi('Attendance rate',stats.hasAttendance?percent(stats.attendanceRate):'—',`${stats.present} present / ${stats.total} students${stats.hasAttendance?'':' · Unmarked'}`,'attendance',changeIndicator(stats,previous,'attendanceRate','hasAttendance'))}${kpi('Homework completion',stats.hasHomework?percent(stats.homeworkRate):'—',`${stats.complete} complete / ${stats.total} students${stats.hasHomework?'':' · Unmarked'}`,'homework',changeIndicator(stats,previous,'homeworkRate','hasHomework'))}${kpi('Staff signed in',stats.onShift,`${stats.completedShifts} signed out for this date`,'staff',countChange(stats,previous,'onShift','staff'))}${kpi('Pending pickups / incidents',`${stats.pending} / ${stats.openIncidents}`,'Awaiting pickup / unresolved reports','shield',countChange(stats,previous,'pending','awaiting pickup',true))}</div>
    <div class="dashboard-chart-grid"><section class="card dashboard-chart"><div class="section-heading"><div><h3>Group snapshot</h3><p>Attendance &amp; homework · student counts</p></div><span class="chart-caption">${stats.total} enrolled</span></div><div class="chart-legend">${['Present','Tardy','Absent','Homework complete'].map((label,i)=>`<span><i style="--dot:${colors[i]}"></i>${label}</span>`).join('')}</div>${groupChart}<p class="chart-note">Unmarked attendance is not counted as absent. Hover or focus a group for its totals.</p></section>
    <section class="card dashboard-chart"><div class="section-heading"><div><h3>7-day program trend</h3><p>${e(dashboardDate(weekDays(day)[0]))} – ${e(dashboardDate(day))}</p></div><span class="chart-caption">Recorded rates</span></div><div class="chart-legend"><span><i style="--dot:#1684a0"></i>Attendance</span><span><i style="--dot:#8a83c2"></i>Homework</span></div><div class="chart-scroll">${trend}</div><p class="chart-note">${historyStatus==='partial'?'Some dates could not be loaded. ':''}Gaps mean unmarked or unavailable data. Rates use the current active roster; historical enrollment is not available.</p></section></div>
    <div class="dashboard-bottom-grid"><section class="card operations-pulse"><div class="section-heading"><div><h3>Operations pulse</h3><p>${day===data.today?'Today’s activity and staff status':'Activity and staff status for this date'}</p></div><span class="soft-pill">${stats.onShift} on shift</span></div>
      <div class="pulse-row"><span class="pulse-icon">${uiIcon('schedule')}</span><div><strong>${day===data.today?'On the schedule now':'Published schedule'}</strong>${currentBlocks.length?currentBlocks.slice(0,4).map(block=>`<p>${e(block.activity)} <span class="muted">· ${e(block.group)} · ${e(block.start)}–${e(block.end)}</span></p>`).join(''):`<p class="muted">${scheduleUnavailable?'Schedule could not be loaded. Open Schedule to retry.':schedule?.groups.some(g=>g.published)?'No activity in this time block.':'No published timetable available. Open Schedule to review.'}</p>`}</div></div>
      <div class="pulse-row"><span class="pulse-icon">${uiIcon('staff')}</span><div><strong>Staff check-ins</strong><p>${onShift.length?onShift.map(event=>e(event.teacher)).join(', '):'No staff currently signed in for this date.'}</p><small class="muted">Status reflects the latest loaded records.</small></div></div>
      <div class="pulse-row"><span class="pulse-icon">${uiIcon('incident')}</span><div><strong>${stats.openIncidents} unresolved incident${stats.openIncidents===1?'':'s'}</strong><p class="muted">${stats.openIncidents?'Open Incidents to review and resolve reports.':'No open reports need attention for this date.'}</p></div></div></section>
    <section class="card dashboard-actions"><div class="section-heading"><div><h3>Quick actions</h3><p>Pick up where your team needs you.</p></div></div>${[['roster','Mark attendance','Review attendance and homework','attendance'],['incidents','Log incident','Record or review a report','incident'],['pickup','Verify pickup','Check authorized contacts','shield']].map(([target,label,detail,icon])=>`<button type="button" class="quick-action" data-dashboard-go="${target}"><span class="quick-icon">${uiIcon(icon)}</span><span><strong>${label}</strong><small>${detail}</small></span>${uiIcon('arrow')}</button>`).join('')}</section></div></div>`;
}

